# Authorized P0: local read-only, allowlisted metadata; no SDK, network or elevation.
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$OutputEncoding = [System.Text.UTF8Encoding]::new($false)
[Console]::OutputEncoding = $OutputEncoding
Import-Module "$PSHOME/Modules/Microsoft.PowerShell.Utility/Microsoft.PowerShell.Utility.psd1" -ErrorAction Stop

$result = [ordered]@{
    started_at_utc = [DateTime]::UtcNow.ToString('o')
    token_is_administrator = $null
    status = 'Not run'
    groups = [ordered]@{}
}
try {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    try {
        $principal = [Security.Principal.WindowsPrincipal]::new($identity)
        $result.token_is_administrator = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } finally { $identity.Dispose() }
} catch {
    $result.status = 'Blocked: token check unavailable; no host queries attempted'
    $result | ConvertTo-Json -Depth 8 -Compress
    exit 3
}
if ($result.token_is_administrator) {
    $result.status = 'Blocked: elevated context; no host queries attempted'
    $result | ConvertTo-Json -Depth 8 -Compress
    exit 3
}

function Read-Group([string]$Name, [scriptblock]$Body) {
    try {
        $data = & $Body
        $result.groups[$Name] = [ordered]@{status = 'Observed'; data = $data}
    } catch {
        # Do not dump exceptions containing computer/account/device identifiers.
        $result.groups[$Name] = [ordered]@{
            status = 'Unknown: query failed; no elevation or retry'
            error_type = $_.Exception.GetType().FullName
            hresult = $_.Exception.HResult
        }
    }
}
function Read-Cim([string]$Query) {
    Get-CimInstance -Namespace root/cimv2 -Query $Query -OperationTimeoutSec 12 -ErrorAction Stop
}
function Bytes-FromKiB($Value) {
    if ($null -eq $Value) { return $null }
    return ([uint64]$Value * 1024)
}

try {
    Import-Module "$PSHOME/Modules/CimCmdlets/CimCmdlets.psd1" -ErrorAction Stop
    Read-Group 'os' {
        $os = Read-Cim 'SELECT Caption,Version,BuildNumber,OSArchitecture,TotalVisibleMemorySize,FreePhysicalMemory FROM Win32_OperatingSystem'
        if ($null -eq $os) { throw [InvalidOperationException]::new('No OS record') }
        [ordered]@{caption=$os.Caption; version=$os.Version; build=$os.BuildNumber; architecture=$os.OSArchitecture; visible_memory_bytes=(Bytes-FromKiB $os.TotalVisibleMemorySize); available_memory_bytes=(Bytes-FromKiB $os.FreePhysicalMemory)}
    }
    Read-Group 'os_release' {
        $base = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, [Microsoft.Win32.RegistryView]::Registry64)
        try {
            $key = $base.OpenSubKey('SOFTWARE\Microsoft\Windows NT\CurrentVersion', $false)
            if ($null -eq $key) { throw [InvalidOperationException]::new('Release key unavailable') }
            try { [ordered]@{display_version=$key.GetValue('DisplayVersion', $null); update_build_revision=$key.GetValue('UBR', $null)} }
            finally { $key.Dispose() }
        } finally { $base.Dispose() }
    }
    Read-Group 'cpu' {
        $items = @(Read-Cim 'SELECT Name,Architecture,NumberOfCores,NumberOfLogicalProcessors,VirtualizationFirmwareEnabled,SecondLevelAddressTranslationExtensions,VMMonitorModeExtensions FROM Win32_Processor')
        if ($items.Count -eq 0) { throw [InvalidOperationException]::new('No CPU record') }
        @($items | ForEach-Object { [ordered]@{model=$_.Name.Trim(); architecture_code=$_.Architecture; cores=$_.NumberOfCores; logical_processors=$_.NumberOfLogicalProcessors; virtualization_firmware_enabled=$_.VirtualizationFirmwareEnabled; slat=$_.SecondLevelAddressTranslationExtensions; vm_monitor_mode_extensions=$_.VMMonitorModeExtensions} })
    }
    Read-Group 'system' {
        $system = Read-Cim 'SELECT TotalPhysicalMemory,HypervisorPresent FROM Win32_ComputerSystem'
        if ($null -eq $system) { throw [InvalidOperationException]::new('No system record') }
        [ordered]@{reported_physical_memory_bytes=$system.TotalPhysicalMemory; hypervisor_present=$system.HypervisorPresent}
    }
    Read-Group 'installed_memory' {
        $items = @(Read-Cim 'SELECT Capacity FROM Win32_PhysicalMemory')
        if ($items.Count -eq 0) { throw [InvalidOperationException]::new('No module capacity record') }
        [uint64]$sum = 0
        foreach ($item in $items) {
            if ($null -eq $item.Capacity -or $item.Capacity -eq 0) { throw [InvalidOperationException]::new('Module capacity unknown') }
            $sum += [uint64]$item.Capacity
        }
        [ordered]@{module_capacity_sum_bytes=$sum}
    }
    Read-Group 'temporary_volume' {
        $disk = Read-Cim "SELECT Size,FreeSpace FROM Win32_LogicalDisk WHERE DeviceID='C:' AND DriveType=3"
        if ($null -eq $disk) { throw [InvalidOperationException]::new('Expected local temporary-data volume unavailable') }
        [ordered]@{role='temporary data'; capacity_bytes=$disk.Size; free_bytes=$disk.FreeSpace}
    }
    Read-Group 'checkout_volume' {
        $disk = Read-Cim "SELECT Size,FreeSpace FROM Win32_LogicalDisk WHERE DeviceID='D:' AND DriveType=3"
        if ($null -eq $disk) { throw [InvalidOperationException]::new('Expected local checkout volume unavailable') }
        [ordered]@{role='checkout'; capacity_bytes=$disk.Size; free_bytes=$disk.FreeSpace}
    }
    Read-Group 'graphics' {
        $items = @(Read-Cim 'SELECT Name,DriverVersion FROM Win32_VideoController')
        if ($items.Count -eq 0) { throw [InvalidOperationException]::new('No graphics record') }
        @($items | ForEach-Object { [ordered]@{model=$_.Name; driver_version=$_.DriverVersion} })
    }
    $result.status = 'Inventory queries finished; null fields remain Unknown, not false'
} catch {
    $result.status = 'Blocked: built-in module unavailable; no alternate tool or elevation'
    $result.error_type = $_.Exception.GetType().FullName
    $result.hresult = $_.Exception.HResult
}
$result.finished_at_utc = [DateTime]::UtcNow.ToString('o')
$result | ConvertTo-Json -Depth 8 -Compress

